export type SelectedJobPlatform = {
  id: string;
  platformSlug: string;
  recommendationLabel: string;
  whySelected: string;
  bestRoleCategories: CareerLane[];
};

export type CuratedJob = {
  id: string;
  title: string;
  company: string;
  companyLogo?: string;
  category: CareerLane;
  roleSlug?: string;
  location: string;
  remote: boolean;
  seniority: string;
  employmentType?: string;
  salary?: string;
  source: string;
  sourceUrl: string;
  applyUrl: string;
  publishedAt?: string;
  addedAt: string;
  kraftNote: string;
  isFeatured: boolean;
  isSelectedByKraft: boolean;
  status: "active" | "expired" | "draft";
};

