export const curatedJobs: CuratedJob[] = generatedJobs as CuratedJob[];

export function getActiveCuratedJobs() {
  return curatedJobs
    .filter((job) => job.status === "active")
    .sort((a, b) => new Date(b.addedAt).getTime() - new Date(a.addedAt).getTime());
}

